SELECT SUM(ContractValue) AS TotalContractValue
FROM reporting.vJobFinancials
WHERE Region = @region;

SELECT COUNT(*) AS JobCount
FROM reporting.vJobs
WHERE Status = 'Completed';

SELECT COUNT(*) AS JobCount
FROM reporting.vJobs
WHERE StartDate >= '2025-01-01' AND StartDate < '2025-02-01';

SELECT ROUND(AVG(ContractValue), 2) AS AverageValue
FROM reporting.vJobs
WHERE Status = 'Completed';

SELECT TOP 10 JobId, TotalInvoiced, TotalExpenses, GrossMargin
FROM reporting.vJobFinancials
ORDER BY JobId ASC;

SELECT SUM(Amount) AS TotalInvoiced
FROM reporting.vInvoices
WHERE YEAR(InvoiceDate) = 2024;

SELECT COALESCE(SUM(Amount), 0) AS TotalInvoiced
FROM reporting.vInvoices
WHERE YEAR(InvoiceDate) = 2024;
